(6, 3, 'en', 'How to Start a Blog in 2026', 'how-to-start-a-blog-in-2026', 'From domain purchase to your first post — the complete walkthrough.', '\"<p>Starting a blog is easier than ever in 2026 \\u2014 and more competitive.<\\/p><h2>Pick your niche<\\/h2><p>Start narrow, grow wide.<\\/p><h2>Choose a platform<\\/h2><p>Static site, headless CMS or classic WordPress?<\\/p>\"', NULL, NULL, NULL, NULL, '2026-05-11 04:01:26', '2026-05-11 04:01:26'),
(23, 12, 'de', 'Web Performance optimieren', 'web-performance-optimieren-1', 'Konkrete Techniken, die Ihre Seite messbar schneller machen.', '\"<p>Schnelle Seiten ranken besser und konvertieren besser.<\\/p><h2>Bilder<\\/h2><p>Modernes Format (WebP\\/AVIF), passende Gr\\u00f6\\u00dfe, Lazy Loading.<\\/p><h2>JavaScript<\\/h2><p>Code-Splitting und Dead-Code Elimination.<\\/p>\"', NULL, NULL, NULL, NULL, '2026-05-11 04:01:26', '2026-05-11 04:01:26'),
(24, 12, 'en', 'Web Performance Optimization', 'web-performance-optimization', 'Concrete techniques that make your site measurably faster.', '\"<p>Fast sites rank better and convert better.<\\/p><h2>Images<\\/h2><p>Modern format (WebP\\/AVIF), correct size, lazy loading.<\\/p><h2>JavaScript<\\/h2><p>Code splitting and dead-code elimination.<\\/p>\"', NULL, NULL, NULL, NULL, '2026-05-11 04:01:26', '2026-05-11 04:01:26');

