INSERT INTO `company_faq_translation` (`id`, `faq_id`, `lang`, `question`, `answer`, `created_at`, `updated_at`) VALUES
(55, 28, 'de', 'Machen Sie auch nur einzelne Möbelstücke?', 'Ja, auch Einzeltransporte innerhalb Berlins ab 49 €. Klavier ausgenommen.', '2026-07-22 01:57:18', '2026-07-22 01:57:18'),
(56, 28, 'en', 'Do you also transport individual pieces?', 'Yes, single-item transports within Berlin start at 49 €. Pianos excluded.', '2026-07-22 01:57:18', '2026-07-22 01:57:18'),
(57, 29, 'de', 'Kann ich beim Umzug mithelfen?', 'Klar — viele unserer Studentenkunden packen selbst mit an. Das drückt den Preis nochmal um 15 %.', '2026-07-22 01:57:18', '2026-07-22 01:57:18'),
(58, 29, 'en', 'Can I help during the move?', 'Of course — many of our student customers help pack. That drops the price another 15 %.', '2026-07-22 01:57:18', '2026-07-22 01:57:18'),
(59, 30, 'de', 'Wie ist Ihre Absage-Regelung?', 'Absage bis 48 Stunden vor Umzug kostenfrei. Danach berechnen wir eine Ausfallpauschale von 30 %.', '2026-07-22 01:57:18', '2026-07-22 01:57:18'),
(60, 30, 'en', 'What is your cancellation policy?', 'Free cancellation up to 48 hours before the move. After that we charge a 30 % cancellation fee.', '2026-07-22 01:57:18', '2026-07-22 01:57:18'),
(61, 31, 'de', 'Wie schnell antworten Sie auf eine Anfrage?', 'Meistens innerhalb von 2–4 Stunden. Bei kurzfristigen Umzügen erreichen Sie uns am besten telefonisch.', '2026-07-22 07:38:34', '2026-07-22 07:38:34'),
(62, 31, 'en', 'How fast do you respond to a request?', 'Usually within 2–4 hours. For last-minute moves it is best to call us directly.', '2026-07-22 07:38:34', '2026-07-22 07:38:34'),
(63, 32, 'de', 'Bieten Sie auch Entrümpelung an?', 'Ja — Entrümpelung ist Teil unseres Angebots. Wir übernehmen die komplette Räumung inklusive fachgerechter Entsorgung.', '2026-07-22 07:38:34', '2026-07-22 07:38:34'),
(64, 32, 'en', 'Do you also do clearance work?', 'Yes — full clearance is part of our service, including proper disposal.', '2026-07-22 07:38:34', '2026-07-22 07:38:34'),
(65, 33, 'de', 'Sind Sie am Wochenende erreichbar?', 'Samstags von 8–16 Uhr. Sonntags nach Absprache — ein Wochenendumzug ist bei uns 10 % teurer als werktags.', '2026-07-22 07:38:34', '2026-07-22 07:38:34'),
(66, 33, 'en', 'Are you available on weekends?', 'Saturdays 8am–4pm. Sundays by arrangement — weekend moves are 10 % more expensive than weekdays.', '2026-07-22 07:38:34', '2026-07-22 07:38:34'),
(153, 77, 'de', 'Wodurch zeichnet sich Ihr Unternehmen aus?', 'Dieses Umzugsunternehmen hat diese Frage noch nicht beantwortet.', '2026-07-24 04:51:14', '2026-07-24 04:51:14'),
(154, 77, 'en', 'What makes your company stand out?', 'This moving company has not yet answered this question.', '2026-07-24 04:51:14', '2026-07-24 04:51:14'),
(155, 78, 'de', 'Wie sieht Ihre Versicherungspolitik aus? Wie gehen Sie mit beschädigten Gegenständen um?', 'Dieses Umzugsunternehmen hat diese Frage noch nicht beantwortet.', '2026-07-24 04:51:14', '2026-07-24 04:51:14'),
(156, 78, 'en', 'What is your insurance policy? How do you handle damaged items?', 'This moving company has not yet answered this question.', '2026-07-24 04:51:14', '2026-07-24 04:51:14'),
(157, 79, 'de', 'Was ist der beste Rat, den Sie Ihren Kunden geben würden?', 'Dieses Umzugsunternehmen hat diese Frage noch nicht beantwortet.', '2026-07-24 04:51:14', '2026-07-24 04:51:14'),
(158, 79, 'en', 'What is the best advice you would give your customers?', 'This moving company has not yet answered this question.', '2026-07-24 04:51:14', '2026-07-24 04:51:14'),
(165, 83, 'de', 'Wodurch zeichnet sich Ihr Unternehmen aus?', 'Dieses Umzugsunternehmen hat diese Frage noch nicht beantwortet.', '2026-07-28 05:06:37', '2026-07-28 05:06:37'),
