CREATE TABLE `company_reviews` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `company_id` bigint(20) UNSIGNED NOT NULL,
  `user_id` bigint(20) UNSIGNED DEFAULT NULL,
  `author_name` varchar(120) NOT NULL,
  `author_email` varchar(190) NOT NULL,
  `author_initials` varchar(8) NOT NULL,
  `is_anonymous` tinyint(1) NOT NULL DEFAULT 0,
  `rating` tinyint(3) UNSIGNED NOT NULL,
  `body` text NOT NULL,
  `advantages` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`advantages`)),
  `disadvantages` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`disadvantages`)),
  `source` varchar(40) DEFAULT NULL,
  `proof_document` varchar(255) DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'published',
  `reply_body` text DEFAULT NULL,
  `replied_at` timestamp NULL DEFAULT NULL,
  `reply_by_user_id` bigint(20) UNSIGNED DEFAULT NULL,
  `helpful_count` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `ip_address` varchar(45) DEFAULT NULL,
  `user_agent` varchar(255) DEFAULT NULL,
  `email_verified_at` timestamp NULL DEFAULT NULL,
  `published_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data for table `company_reviews`
--

INSERT INTO `company_reviews` (`id`, `company_id`, `user_id`, `author_name`, `author_email`, `author_initials`, `is_anonymous`, `rating`, `body`, `advantages`, `disadvantages`, `source`, `proof_document`, `status`, `reply_body`, `replied_at`, `reply_by_user_id`, `helpful_count`, `ip_address`, `user_agent`, `email_verified_at`, `published_at`, `created_at`, `updated_at`) VALUES
(1, 1, NULL, 'Sarai Doyle', 'rosenbaum.kelli@example.com', 'S.D.', 1, 5, 'Wir waren begeistert. Das Team von Moovato war pünktlich, freundlich und hat unseren gesamten Hausrat mit größter Sorgfalt verpackt. Auch das Klavier haben sie ohne einen Kratzer transportiert. Preis-Leistung absolut fair — jederzeit wieder!', '[\"friendly\",\"professional\",\"careful\",\"on-time\"]', '[]', 'google', NULL, 'published', 'Vielen Dank für Ihr Vertrauen und die tolle Bewertung! Es hat uns sehr gefreut, Sie beim Umzug unterstützen zu dürfen. Wir wünschen viel Freude im neuen Zuhause. — Ihr Moovato-Team', '2026-08-21 04:28:16', 1, 26, '155.176.8.97', 'Mozilla/5.0 (Macintosh; U; PPC Mac OS X 10_5_1 rv:6.0) Gecko/20120330 Firefox/37.0', '2026-07-23 00:55:12', '2026-07-23 01:55:12', '2026-08-04 01:55:14', '2026-08-21 04:28:16'),
(2, 1, NULL, 'Rey Price', 'rachael68@example.com', 'R.P.', 0, 5, 'Von der ersten Anfrage bis zur letzten Kiste alles top. Der Kostenvoranschlag war transparent, keine versteckten Gebühren. Am Umzugstag stand das Team pünktlich vor der Tür und alles war innerhalb von 4 Stunden erledigt. Klare Empfehlung!', '[\"fast\",\"reliable\",\"fair-pricing\",\"communicative\"]', '[]', 'referred', NULL, 'published', NULL, NULL, NULL, 9, '10.76.183.43', 'Mozilla/5.0 (Macintosh; U; PPC Mac OS X 10_5_3) AppleWebKit/5322 (KHTML, like Gecko) Chrome/38.0.854.0 Mobile Safari/5322', '2026-07-11 00:55:14', '2026-07-11 01:55:14', '2026-08-04 01:55:14', '2026-08-21 04:28:15'),
(3, 1, NULL, 'Genoveva Shanahan I', 'karli80@example.org', 'G.I.', 0, 4, 'Alles hat gut geklappt. Die Möbelmontage war einwandfrei und die Mitarbeiter sehr höflich. Einzig die Kommunikation im Vorfeld hätte etwas besser sein können — es dauerte 2 Tage, bis wir einen Rückruf bekamen. Trotzdem ein guter Umzug!', '[\"professional\",\"friendly\"]', '[\"communicative\"]', 'website', NULL, 'published', 'Danke für die ehrliche Rückmeldung. Wir nehmen die Kritik ernst und arbeiten kontinuierlich daran, unsere Kommunikation zu verbessern. Sollten Sie noch offene Punkte haben, melden Sie sich gerne direkt bei uns.', '2026-08-21 04:28:15', 1, 20, '18.142.155.5', 'Mozilla/5.0 (Windows; U; Windows NT 5.0) AppleWebKit/535.18.1 (KHTML, like Gecko) Version/4.1 Safari/535.18.1', '2026-06-29 00:55:14', '2026-06-29 01:55:14', '2026-08-04 01:55:14', '2026-08-21 04:28:15'),
(4, 1, NULL, 'Kristoffer Kuhlman', 'boyd04@example.org', 'K.K.', 0, 5, 'Super Team, super Service. Wir sind aus einer 4-Zimmer-Wohnung im 3. Stock (ohne Aufzug!) in ein Haus umgezogen. Alles ist heil angekommen. Danke an das gesamte Team!', '[\"friendly\",\"fast\",\"careful\"]', '[]', 'google', NULL, 'published', NULL, NULL, NULL, 8, '1.205.73.122', 'Mozilla/5.0 (compatible; MSIE 6.0; Windows 98; Win 9x 4.90; Trident/3.0)', '2026-06-17 00:55:14', '2026-06-17 01:55:14', '2026-08-04 01:55:14', '2026-08-21 04:28:15'),
(5, 1, NULL, 'Berenice Cartwright', 'catherine.corkery@example.org', 'B.C.', 1, 3, 'Der Umzug an sich verlief ordentlich. Leider gab es beim Aufbau ein paar Kratzer am Schrank, die vorher nicht dokumentiert waren. Nach Reklamation hat man sich immerhin schnell gekümmert und eine Erstattung angeboten.', '[\"communicative\"]', '[\"careful\"]', 'social', NULL, 'published', NULL, NULL, NULL, 17, '153.180.180.45', 'Mozilla/5.0 (Macintosh; PPC Mac OS X 10_8_0 rv:4.0) Gecko/20211213 Firefox/36.0', '2026-06-05 00:55:14', '2026-06-05 01:55:14', '2026-08-04 01:55:14', '2026-08-21 04:28:15'),
(6, 2, NULL, 'Conrad McLaughlin', 'konopelski.bud@example.com', 'C.M.', 0, 5, 'Wir waren begeistert. Das Team von Moovato war pünktlich, freundlich und hat unseren gesamten Hausrat mit größter Sorgfalt verpackt. Auch das Klavier haben sie ohne einen Kratzer transportiert. Preis-Leistung absolut fair — jederzeit wieder!', '[\"friendly\",\"professional\",\"careful\",\"on-time\"]', '[]', 'google', NULL, 'published', 'Vielen Dank für Ihr Vertrauen und die tolle Bewertung! Es hat uns sehr gefreut, Sie beim Umzug unterstützen zu dürfen. Wir wünschen viel Freude im neuen Zuhause. — Ihr Moovato-Team', '2026-07-25 01:55:14', 1, 25, '152.69.77.73', 'Opera/9.31 (Windows NT 5.01; nl-NL) Presto/2.12.168 Version/11.00', '2026-07-23 00:55:14', '2026-07-23 01:55:14', '2026-08-04 01:55:14', '2026-08-04 01:55:14'),
(7, 2, NULL, 'Isabel Wintheiser', 'olemke@example.com', 'I.W.', 0, 5, 'Von der ersten Anfrage bis zur letzten Kiste alles top. Der Kostenvoranschlag war transparent, keine versteckten Gebühren. Am Umzugstag stand das Team pünktlich vor der Tür und alles war innerhalb von 4 Stunden erledigt. Klare Empfehlung!', '[\"fast\",\"reliable\",\"fair-pricing\",\"communicative\"]', '[]', 'referred', NULL, 'published', NULL, NULL, NULL, 16, '77.67.163.16', 'Opera/8.95 (Windows NT 5.01; sl-SI) Presto/2.11.202 Version/10.00', '2026-07-11 00:55:14', '2026-07-11 01:55:14', '2026-08-04 01:55:14', '2026-08-04 01:55:14'),
(8, 2, NULL, 'Ocie Kling', 'shanahan.delia@example.org', 'O.K.', 0, 4, 'Alles hat gut geklappt. Die Möbelmontage war einwandfrei und die Mitarbeiter sehr höflich. Einzig die Kommunikation im Vorfeld hätte etwas besser sein können — es dauerte 2 Tage, bis wir einen Rückruf bekamen. Trotzdem ein guter Umzug!', '[\"professional\",\"friendly\"]', '[\"communicative\"]', 'website', NULL, 'published', 'Danke für die ehrliche Rückmeldung. Wir nehmen die Kritik ernst und arbeiten kontinuierlich daran, unsere Kommunikation zu verbessern. Sollten Sie noch offene Punkte haben, melden Sie sich gerne direkt bei uns.', '2026-07-01 01:55:14', 1, 14, '185.207.162.223', 'Mozilla/5.0 (X11; Linux x86_64; rv:5.0) Gecko/20191004 Firefox/37.0', '2026-06-29 00:55:14', '2026-06-29 01:55:14', '2026-08-04 01:55:14', '2026-08-04 01:55:14'),
(9, 2, NULL, 'Linnea Walker', 'oconner.rylee@example.com', 'L.W.', 0, 5, 'Super Team, super Service. Wir sind aus einer 4-Zimmer-Wohnung im 3. Stock (ohne Aufzug!) in ein Haus umgezogen. Alles ist heil angekommen. Danke an das gesamte Team!', '[\"friendly\",\"fast\",\"careful\"]', '[]', 'google', NULL, 'published', NULL, NULL, NULL, 2, '13.222.18.53', 'Opera/8.20 (Windows NT 5.01; en-US) Presto/2.12.226 Version/12.00', '2026-06-17 00:55:14', '2026-06-17 01:55:14', '2026-08-04 01:55:14', '2026-08-04 01:55:14'),
