INSERT INTO `company_translation` (`id`, `company_id`, `lang`, `name`, `permalink`, `short_description`, `about`, `created_at`, `updated_at`) VALUES
(1, 1, 'de', 'Moovato Umzüge Berlin j', 'moovato-umzuege-berlin', 'Ihr zuverlässiges Umzugsunternehmen in Berlin — von Mitte bis Spandau.', 'Moovato ist ein modernes Umzugsunternehmen mit Sitz in Berlin-Mitte. Seit 2011 organisieren wir Privatumzüge, Firmenumzüge und Fernumzüge in ganz Deutschland und Europa. Unser 32-köpfiges Team bietet Ihnen einen Rundum-Service inklusive Verpackung, Montage und Entsorgung. Alle Fahrzeuge sind versichert, alle Mitarbeiter geschult und sozialversichert. Vertrauen Sie auf über 280 positive Bewertungen und einen Weiterempfehlungswert von 98 %.', '2026-07-21 06:11:55', '2026-08-11 04:23:34'),
(2, 1, 'en', 'Moovato Movers Berlin', 'moovato-movers-berlin', 'Short English description.', 'New text in English — smoke test.', '2026-07-21 06:11:55', '2026-08-11 04:23:34'),
(3, 2, 'de', 'Zügig Berlin Umzüge GmbH', 'zuegig-berlin-umzuege', 'Schnell, ehrlich, bezahlbar — Ihr Umzugsteam aus Kreuzberg.', 'Die Zügig Berlin Umzüge GmbH ist ein kleines familiengeführtes Umzugsunternehmen aus Kreuzberg. Seit 2015 helfen wir Berlinern bei Privatumzügen, Büroumzügen und Entrümpelungen. Faire Preise, transparente Kalkulation und ein Team, das anpackt statt zu erklären.', '2026-07-21 06:11:55', '2026-07-21 06:11:55'),
(4, 2, 'en', 'Zügig Berlin Movers GmbH', 'zuegig-berlin-movers', 'Fast, honest, affordable — your moving crew from Kreuzberg.', 'Zügig Berlin Movers is a small family-run moving company from Kreuzberg. Since 2015 we have helped Berliners with private moves, office relocations and clearance work. Fair prices, transparent quotes, and a team that gets the job done.', '2026-07-21 06:11:55', '2026-07-21 06:11:55'),
(5, 3, 'de', 'Hauptstadt Movers Neukölln', 'hauptstadt-movers-neukoelln', 'Junges Umzugsteam mit fairen Preisen — spezialisiert auf Studentenumzüge.', 'Hauptstadt Movers ist ein junges Umzugsunternehmen aus Neukölln. Wir haben uns auf kleinere Umzüge spezialisiert: WG-Zimmer, Studenten, Einzelpersonen. Preiswert, unkompliziert, verlässlich.', '2026-07-21 06:11:55', '2026-07-21 06:11:55'),
(6, 3, 'en', 'Hauptstadt Movers Neukölln', 'hauptstadt-movers-neukoelln-en', 'Young moving team with fair prices — specialised in student moves.', 'Hauptstadt Movers is a young moving company from Neukölln. We specialise in smaller moves: shared flats, students, single-person households. Affordable, uncomplicated, reliable.', '2026-07-21 06:11:55', '2026-07-21 06:11:55'),
(23, 14, 'de', 'Umzugsgenie', 'umzugsgenie', 'Jeder Umzug wird ausführlich und ausschließlich nach Ihren Wünschen und Vorstellungen geplant und realisiert.', '<p><span style=\"color: rgb(0, 0, 131); font-family: Basier, sans-serif; font-size: 16px;\">Sie planen einen Umzug von oder nach Berlin und suchen eine professionelle Umzugsfirma Berlin, das Sie bei Ihrem Vorhaben unterstützt? Dann haben Sie mit uns den richtigen Ansprechpartner an Ihrer Seite gefunden. Umzugsgenie führt europaweit Umzüge aller Art durch und verfügt über eine jahrelange Erfahrung. Jeder Umzug wird ausführlich und ausschließlich nach Ihren Wünschen und Vorstellungen geplant und realisiert.</span><br></p>', '2026-07-23 23:41:06', '2026-07-24 02:49:27'),
(25, 14, 'en', 'Moving genius', 'moving-genius', 'Every move is planned and executed in detail and exclusively according to your wishes and requirements.', '<p>Are you planning a move to or from Berlin and looking for a professional Berlin moving company to support you? Then you\'ve come to the right place. Umzugsgenie carries out all types of moves throughout Europe and has years of experience. Every move is planned and executed in detail and exclusively according to your wishes and requirements.</p>', '2026-07-24 00:35:39', '2026-07-24 04:51:14'),
(38, 23, 'de', 'Tiger  Umzugsunternehmen', 'tiger-umzugsunternehmen', 'Jeder Umzug wird ausführlich und ausschließlich nach Ihren Wünschen und Vorstellungen geplant und realisiert.', '<p><span style=\"color: rgb(0, 0, 131); font-family: Basier, sans-serif; font-size: 16px;\">Sie planen einen Umzug von oder nach Berlin und suchen eine professionelle Umzugsfirma Berlin, das Sie bei Ihrem Vorhaben unterstützt? Dann haben Sie mit uns den richtigen Ansprechpartner an Ihrer Seite gefunden. Umzugsgenie führt europaweit Umzüge aller Art durch und verfügt über eine jahrelange Erfahrung. Jeder Umzug wird ausführlich und ausschließlich nach Ihren Wünschen und Vorstellungen geplant und realisiert.</span></p>', '2026-07-27 04:33:15', '2026-07-28 04:10:51'),
(39, 23, 'en', 'Tiger Packers and Movers', 'tiger-packers-and-movers', 'Every move is planned and executed in detail and exclusively according to your wishes and requirements.', '<p>Are you planning a move to or from Berlin and looking for a professional Berlin moving company to support you? Then you\'ve come to the right place. Umzugsgenie carries out all types of moves throughout Europe and has years of experience. Every move is planned and executed in detail and exclusively according to your wishes and requirements.</p>', '2026-07-27 04:33:15', '2026-07-28 04:10:51'),
(41, 25, 'de', 'Allied Movers and Packers', 'allied-movers-and-packers', 'Since 2011 we have handled private moves, corporate relocations and long-distance moves across Germany and Europe', '<p><span style=\"color: rgb(71, 85, 105); font-family: &quot;DM Sans&quot;, ui-sans-serif, system-ui, sans-serif; font-size: 16px;\">Moovato is a modern moving company headquartered in Berlin-Mitte. Since 2011 we have handled private moves, corporate relocations and long-distance moves across Germany and Europe. Our team of 32 delivers a full-service experience including packing, assembly and disposal. All vehicles are insured, all staff trained and fully employed. Trust more than 280 positive reviews and a 98 % recommendation rate.</span></p>', '2026-08-07 05:28:33', '2026-08-07 05:35:59'),
(42, 25, 'en', 'Allied Movers and Packers', 'allied-movers-and-packers', NULL, NULL, '2026-08-07 05:35:59', '2026-08-07 05:35:59'),
(45, 27, 'de', 'Mover Packers', 'mover-packers', 'All vehicles are insured, all staff trained and fully employed. Trust more than 280 positive reviews and a 98 % recommendation rate.', '<p><span style=\"color: rgb(71, 85, 105); font-family: &quot;DM Sans&quot;, ui-sans-serif, system-ui, sans-serif; font-size: 16px;\">Moovato is a modern moving company headquartered in Berlin-Mitte. Since 2011 we have handled private moves, corporate relocations and long-distance moves across Germany and Europe. Our team of 32 delivers a full-service experience including packing, assembly and disposal. All vehicles are insured, all staff trained and fully employed. Trust more than 280 positive reviews and a 98 % recommendation rate.</span></p>', '2026-08-07 07:25:09', '2026-08-07 07:25:09'),
(46, 27, 'en', 'Mover Packers', 'mover-packers', 'All vehicles are insured, all staff trained and fully employed. Trust more than 280 positive reviews and a 98 % recommendation rate.', '<p><span style=\"color: rgb(71, 85, 105); font-family: &quot;DM Sans&quot;, ui-sans-serif, system-ui, sans-serif; font-size: 16px;\">Moovato is a modern moving company headquartered in Berlin-Mitte. Since 2011 we have handled private moves, corporate relocations and long-distance moves across Germany and Europe. Our team of 32 delivers a full-service experience including packing, assembly and disposal. All vehicles are insured, all staff trained and fully employed. Trust more than 280 positive reviews and a 98 % recommendation rate.</span></p>', '2026-08-07 07:25:09', '2026-08-07 07:25:09'),
